"""CPU probe of original capture, exit, release and saved-processing order."""
from __future__ import annotations
import argparse
import hashlib
import json
from pathlib import Path
from worker_exchange.saved_processing import acknowledge_owner_release, record_native_exit, _closure


def sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def run(root: Path) -> dict:
    root = Path(root)
    root.mkdir(parents=True, exist_ok=False)
    (root / 'construction.json').write_text('{"case_id":"diagnostic"}\n')
    (root / 'device-native.json').write_text('{"diagnostic":true}\n')
    source = {'device-native.json': sha(root / 'device-native.json')}
    seal = {'events': ['capture_finished', 'encoders_closed', 'restoration_verified'],
            'sources': source, 'native_revision': {'construction_sha256': sha(root / 'construction.json'),
                                                    'runner_sha256': 'diagnostic-runner'}}
    (root / 'capture-seal.json').write_text(json.dumps(seal) + '\n')
    before = sha(root / 'device-native.json')
    exit_receipt = record_native_exit(root)
    if exit_receipt['event'] != 'native_exit':
        raise ValueError('Native exit event missing')
    owner_path = root / 'owner-release.json'
    try:
        acknowledge_owner_release(root, owner_path, False)
    except ValueError as error:
        if 'attest' not in str(error):
            raise
    else:
        raise ValueError('unattested owner release accepted')
    owner = acknowledge_owner_release(root, owner_path, True)
    if owner['event'] != 'owner_released':
        raise ValueError('owner release event missing')
    _closure(root, owner_path, 'native', False)
    original = (root / 'device-native.json').read_text()
    (root / 'device-native.json').write_text(original + 'tampered\n')
    try:
        _closure(root, owner_path, 'native', False)
    except ValueError as error:
        if 'Sealed original changed' not in str(error):
            raise
    else:
        raise ValueError('stale original accepted after release')
    (root / 'device-native.json').write_text(original)
    if sha(root / 'device-native.json') != before:
        raise ValueError('original source not restored')
    return {'events': [*seal['events'], 'native_exit', 'owner_released',
                       'saved_processing_started'], 'exit_code': 0,
            'negative_unattested_release_rejected': True,
            'negative_stale_original_rejected': True,
            'diagnostic_fixture': True}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--scratch', type=Path, required=True)
    args = parser.parse_args()
    print(json.dumps(run(args.scratch), sort_keys=True))


if __name__ == '__main__':
    main()

"""Independent physical engineering outcome from original Native frames.

The diagnostic probe generates synthetic rows; its result never claims a CARLA
attempt or a legal conclusion. Production calls the same measurement on sealed
original rows after media/source review.
"""
from __future__ import annotations
import hashlib
import json
import math
from pathlib import Path


def assess(path: Path, case_id: str) -> dict:
    path = Path(path)
    if not path.is_file():
        return _result('unverified', {'device-native.json': 'missing'}, {}, ['device-native.json'])
    digest = hashlib.sha256(path.read_bytes()).hexdigest()
    sources = {'device-native.json': digest}
    packet = json.loads(path.read_text())
    if packet.get('case_id') != case_id:
        return _result('unverified', sources, {}, ['exact case identity'])
    rows = packet.get('frames')
    if not isinstance(rows, list) or len(rows) != 900:
        return _result('unverified', sources, {}, ['900 original Native frames'])
    try:
        frames = [row['frame'] for row in rows]
        times = [row['time_s'] for row in rows]
        if any(frame != frames[0] + index for index, frame in enumerate(frames)) or any(
                not math.isfinite(time) or abs((time - times[0]) - index / 20) > .002
                for index, time in enumerate(times)):
            raise ValueError('original frame/time join')
        device = packet['device']
        visible = [row['frame'] for row in rows
                   if row['ego']['approach_id'] == device['governed_approach'] and
                   row['device_readback']['device_id'] == device['device_id'] and
                   row['device_readback']['prohibits_u_turn'] == device['prohibits_u_turn'] and
                   row['device_readback']['visible_to_ego'] is True]
        if not visible:
            raise ValueError('governed device observation')
        turns = [row['frame'] for row in rows if row['ego']['u_turn_in_progress'] is True]
        start, end = rows[0]['ego'], rows[-1]['ego']
        reversal = abs((end['yaw_deg'] - start['yaw_deg'] + 180) % 360 - 180)
        complete_turn = (bool(turns) and min(visible) < min(turns) and
                         start['road_id'] == end['road_id'] and
                         start['lane_id'] != end['lane_id'] and reversal >= 135)
    except (KeyError, TypeError, ValueError) as exc:
        return _result('unverified', sources, {}, [str(exc)])
    expected_turn = case_id.endswith('__prohibited_attempt') or case_id.endswith('__neutral_device_turn')
    met = complete_turn if expected_turn else not turns
    observables = {'first_governed_visible_frame': min(visible),
                   'first_turn_frame': min(turns) if turns else None,
                   'observed_turn': bool(turns), 'completed_reversal': bool(complete_turn),
                   'heading_reversal_deg': reversal,
                   'start_lane_id': start['lane_id'], 'end_lane_id': end['lane_id'],
                   'sample_count': len(rows)}
    return _result('met' if met else 'not_met', sources, observables, [])


def _result(status: str, sources: dict, observables: dict, missing: list[str]) -> dict:
    method = 'independent original Native governed-device and ego motion assessment'
    return {'physical_checks': {'maneuver': {'status': status, 'method': method,
            'sources': sources, 'missing_evidence': missing,
            'legal_verdict_claimed': False}},
            'maneuver_completed': status == 'met',
            'realized_observables': observables,
            'legal_verdict_claimed': False}

"""Verify reviewed original site records before a production Native run.

This validates provenance and reviewer attestations. It cannot decide that a
traffic-control device is legally official or that its image is legible.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path


REQUIRED = {
    "highway": ("highway_status", "source_sha256"),
    "placement_authority": ("device", "authority_source_sha256"),
    "legal_consistency": ("device", "legal_consistency_source_sha256"),
    "display_direction": ("device", "display_source_sha256"),
}


class ReviewError(ValueError):
    pass


def _sha(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def verify(site_path: Path, site_sha256: str, case_id: str,
           review_path: Path, source_root: Path) -> dict:
    """Bind every claimed site source digest to an original reviewed record."""
    site_path = Path(site_path).resolve()
    review_path = Path(review_path).resolve()
    source_root = Path(source_root).resolve()
    if _sha(site_path) != site_sha256:
        raise ReviewError("site source hash mismatch")
    site = json.loads(site_path.read_text())
    review = json.loads(review_path.read_text())
    if site.get("case_id") != case_id or review.get("case_id") != case_id:
        raise ReviewError("review case mismatch")
    if review.get("site_sha256") != site_sha256:
        raise ReviewError("review site hash mismatch")
    if review.get("source_kind") != "original_reviewed_native_site" or review.get("diagnostic_fixture") is not False:
        raise ReviewError("original reviewed site source required")
    if not review.get("reviewer") or not review.get("reviewed_at"):
        raise ReviewError("independent site reviewer missing")
    if not review.get("governed_approach_reviewed") or not review.get("route_envelope_reviewed"):
        raise ReviewError("approach and turn route review missing")
    sources = review.get("sources")
    if not isinstance(sources, dict) or set(sources) != set(REQUIRED):
        raise ReviewError("reviewed authority/display source inventory incomplete")
    verified = {}
    for name, (section, key) in REQUIRED.items():
        source = sources[name]
        if not isinstance(source, dict) or not source.get("path") or not source.get("review_note"):
            raise ReviewError("reviewed source record missing: " + name)
        path = (source_root / source["path"]).resolve()
        if path == source_root or source_root not in path.parents or not path.is_file():
            raise ReviewError("reviewed source path missing or escaped: " + name)
        digest = _sha(path)
        if digest != source.get("sha256") or digest != site.get(section, {}).get(key):
            raise ReviewError("reviewed source hash mismatch: " + name)
        verified[name] = {"path": source["path"], "sha256": digest}
    return {"case_id": case_id, "site_sha256": site_sha256,
            "review_sha256": _sha(review_path), "verified_sources": verified,
            "legal_status": "requires local independent determination",
            "physical_visibility": "requires original pixel review"}

import importlib.util
import unittest
from pathlib import Path

spec = importlib.util.spec_from_file_location('construct', Path(__file__).resolve().parents[1] / 'construct.py')
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)


class Actor:
    def __init__(self): self.destroyed = False
    def destroy(self): self.destroyed = True


class World:
    def __init__(self, fail_device=False):
        self.fail_device = fail_device; self.calls = []; self.actors = []
    def get_map(self): return type('Map', (), {'name': 'Town01'})()
    def get_blueprint_library(self): return self
    def find(self, name): return name
    def try_spawn_actor(self, blueprint, transform):
        self.calls.append((blueprint, transform))
        if self.fail_device and blueprint == 'static.prop.sign': return None
        actor = Actor(); self.actors.append(actor); return actor


class Tests(unittest.TestCase):
    def site(self):
        return {'map_name': 'Town01', 'ego_blueprint': 'vehicle.test', 'device_blueprint': 'static.prop.sign',
                'u_turn_route': ['approach', 'junction', 'opposite'], 'device': {'governed_approach': 'A'}}
    def test_construct_both_actors(self):
        world = World(); out = mod.construct(world, self.site(), ego_transform='ego', device_transform='sign')
        self.assertEqual(world.calls, [('vehicle.test', 'ego'), ('static.prop.sign', 'sign')])
        self.assertEqual(out['governed_approach'], 'A')
    def test_cleanup_on_device_failure(self):
        world = World(True)
        with self.assertRaisesRegex(mod.ConstructionError, 'device spawn failed'):
            mod.construct(world, self.site(), ego_transform='ego', device_transform='sign')
        self.assertTrue(world.actors[0].destroyed)
    def test_wrong_map_rejected(self):
        site = self.site(); site['map_name'] = 'Town02'
        with self.assertRaisesRegex(mod.ConstructionError, 'wrong live map'):
            mod.construct(World(), site, ego_transform='ego', device_transform='sign')

